import UIKitfinal class AdventureViewController: UIViewController {    @IBOutlet private weak var storyLabel: UILabel!    @IBOutlet private weak var optionsStack: UIStackView!    @IBOutlet private weak var restartButton: UIButton!    private let graph = AdventureFactory.makeGraph()    private var currentNodeID: String = "start"    override func viewDidLoad() {        super.viewDidLoad()        navigationItem.title = "adventure"        // Prevent the label from intercepting touches if its frame overlaps the buttons        storyLabel.isUserInteractionEnabled = false        restartButton.isHidden = true        render(nodeID: currentNodeID)    }    @IBAction private func restartTapped(_ sender: UIButton) {        currentNodeID = "start"        render(nodeID: currentNodeID)    }    private func render(nodeID: String) {        let node = graph.node(with: nodeID)        storyLabel.text = node.narrative        optionsStack.arrangedSubviews.forEach { v in            optionsStack.removeArrangedSubview(v)            v.removeFromSuperview()        }        if node.isEnding {            restartButton.isHidden = false            navigationItem.prompt = node.isSuccess ? "✅ Success Ending" : "❌ Unsuccessful Ending"            return        }        navigationItem.prompt = nil        restartButton.isHidden = true        for option in node.options {            let button = makeOptionButton(title: option.title)            button.addAction(UIAction(handler: { [weak self] _ in                self?.currentNodeID = option.nextNodeID                self?.render(nodeID: option.nextNodeID)            }), for: .touchUpInside)            optionsStack.addArrangedSubview(button)        }    }    private func makeOptionButton(title: String) -> UIButton {        var config = UIButton.Configuration.borderedProminent()        config.title = title        config.cornerStyle = .medium        let button = UIButton(configuration: config)        button.titleLabel?.numberOfLines = 0        button.titleLabel?.textAlignment = .center        return button    }}